const settings = $('Load Global Settings').first()?.json ?? {};
const request = $('Send Case Tracking Email Webhook').first()?.json ?? $input.first()?.json ?? {};
const body = request.body ?? request.query ?? request;
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const validUuid = (value) => /^[0-9a-fA-F-]{36}$/.test(clean(value));
const deriveBaseUrl = (headers, fallback) => {
  const forwardedProto = clean(headers['x-forwarded-proto']);
  const forwardedHost = clean(headers['x-forwarded-host']);
  const host = forwardedHost || clean(headers.host);
  const forwardedPort = clean(headers['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = authority + ':' + forwardedPort;
  }
  return proto + '://' + authority;
};
const normalizeAddressList = (value) => clean(value)
  .replace(/[\r\n]+/g, ' ')
  .split(/[;,]+/)
  .map((part) => clean(part))
  .filter(Boolean)
  .join(', ');
const hasEmailAddress = (value) => /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(clean(value));
const fallbackBaseUrl = clean(settings.n8n_base_url) || 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
const caseId = validUuid(body.case_id) ? clean(body.case_id) : '';
const requestedMode = clean(body.mode).toLowerCase();
const allowedModes = new Set(['new', 'reply', 'reply_all', 'forward']);
const replyToCaseEmailId = validUuid(body.reply_to_case_email_id) ? clean(body.reply_to_case_email_id) : '';
const mode = allowedModes.has(requestedMode) ? requestedMode : (replyToCaseEmailId ? 'reply' : 'new');
const requestedQuoteMode = clean(body.reply_quote_mode).toLowerCase();
const allowedQuoteModes = new Set(['none', 'previous', 'thread', 'forward']);
const returnUrl = clean(body.return_url) || (n8nBaseUrl + '/webhook/case-tracking?view=dashboard');
const deliveryMode = truthy(body.test_mode) ? 'test' : 'production';
const normalizedRecipient = normalizeAddressList(body.to);
const normalizedCc = normalizeAddressList(body.cc);
const emailType = clean(body.email_type) === 'html' ? 'html' : 'text';
const openTrackingEnabled = emailType === 'html' && truthy(body.open_tracking_enabled);
const parentRequired = ['reply', 'reply_all', 'forward'].includes(mode);
const errorMessage = !caseId
  ? 'case_id is required.'
  : (parentRequired && !replyToCaseEmailId
    ? 'reply_to_case_email_id is required for ' + mode + ' mode.'
    : (!hasEmailAddress(normalizedRecipient)
      ? 'A recipient is required.'
      : (!clean(body.rendered_subject)
        ? 'Subject is required.'
        : (!String(body.rendered_message ?? '').trim() ? 'Message is required.' : ''))));
return [{
  json: {
    case_id: caseId,
    mode,
    reply_to_case_email_id: replyToCaseEmailId,
    reply_quote_mode: allowedQuoteModes.has(requestedQuoteMode) ? requestedQuoteMode : '',
    template_key: clean(body.template_key),
    signature_template_key: clean(body.signature_template_key),
    to: normalizedRecipient,
    cc: normalizedCc,
    return_url: returnUrl,
    n8n_base_url: n8nBaseUrl,
    delivery_mode: deliveryMode,
    test_recipient: clean(settings.email_test_recipient) || clean(settings.default_test_recipient) || 'steve.short@gmail.com',
    sender_name: clean(settings.email_sender_name) || 'Steve Short',
    reply_to: clean(settings.email_reply_to) || 'members.avondaleltc@gmail.com',
    rendered_subject: clean(body.rendered_subject),
    rendered_message: body.rendered_message ?? '',
    rendered_signature: body.rendered_signature ?? '',
    email_type: emailType,
    open_tracking_enabled: openTrackingEnabled,
    error_message: errorMessage,
  },
}];

const requestInput = $('Resolve Send Request').first()?.json ?? {};
const message = requestInput.error_message || 'Unable to send the email.';
const redirectTo = (requestInput.return_url || '#') + (((requestInput.return_url || '#').includes('?')) ? '&' : '?') + 'error=' + encodeURIComponent(message);
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=' + escapeHtml(redirectTo) + '"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Email not sent</title></head><body><p>' + escapeHtml(message) + '</p><p><a href="' + escapeHtml(redirectTo) + '">Back to case</a></p></body></html>';
return [{ json: { html } }];

const input = $('Resolve Send Request').first()?.json ?? {};
const result = $('Load Send Context').first()?.json ?? {};
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') { try { return JSON.parse(value); } catch { return fallback; } }
  return value;
};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const caseRow = parseMaybe(result.case_row, {}) || {};
const parentEmailRow = parseMaybe(result.parent_email_row, {}) || {};
const intendedRecipient = clean(input.to);
const intendedCc = clean(input.cc);
const actualRecipient = input.delivery_mode === 'production' ? intendedRecipient : input.test_recipient;
const actualCc = input.delivery_mode === 'production' ? intendedCc : '';
const stripHeaderValue = (value) => clean(value).replace(/[\r\n]+/g, ' ');
const encodeHeaderValue = (value) => {
  const text = stripHeaderValue(value);
  if (!text) return '';
  return /^[\x20-\x7e]*$/.test(text) ? text : '=?UTF-8?B?' + Buffer.from(text, 'utf8').toString('base64') + '?=';
};
const encodeAddress = (name, email) => {
  const address = clean(email);
  const displayName = stripHeaderValue(name).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return displayName ? '"' + displayName + '" <' + address + '>' : address;
};
const sanitizeAddressHeader = (value) => stripHeaderValue(value);
const normalizeMessageId = (value) => {
  const text = clean(value).replace(/[\r\n]+/g, ' ');
  if (!text) return '';
  const match = text.match(/<[^<>\s]+@[^<>\s]+>/);
  return match ? match[0] : text;
};
const uniqueMessageIdChain = (values) => {
  const result = [];
  const seen = new Set();
  for (const value of values) {
    const text = clean(value).replace(/[\r\n]+/g, ' ');
    const ids = text.match(/<[^<>\s]+@[^<>\s]+>/g) || (text ? [text] : []);
    for (const id of ids) {
      const key = id.toLowerCase();
      if (!id || seen.has(key)) continue;
      seen.add(key);
      result.push(id);
    }
  }
  return result.join(' ');
};
const randomToken = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (ch) => {
    const value = Math.floor(Math.random() * 16);
    return (ch === 'x' ? value : ((value & 0x3) | 0x8)).toString(16);
  });
};
const combinedSource = input.email_type === 'html'
  ? String(input.rendered_message || '') + String(input.rendered_signature || '')
  : [String(input.rendered_message || '').trim(), String(input.rendered_signature || '').trim()].filter(Boolean).join('\n\n');
const trackingToken = input.open_tracking_enabled ? randomToken() : '';
const trackingPath = '6f3d9e58-5f0c-4f3e-b29c-1d6c8ef9d4a1.gif';
const trackingUrl = trackingToken ? String(input.n8n_base_url || '').replace(/\/$/, '') + '/webhook/' + trackingPath + '?v=' + encodeURIComponent(trackingToken) : '';
const trackingPixelHtml = trackingUrl ? '<img src="' + trackingUrl.replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '" width="1" height="1" alt="" style="display:none;width:1px;height:1px;border:0;opacity:0" />' : '';
const combinedMessage = input.email_type === 'html' && trackingPixelHtml ? combinedSource + trackingPixelHtml : combinedSource;
const parentInternetMessageId = normalizeMessageId(parentEmailRow.internet_message_id);
const isThreadedReply = ['reply', 'reply_all'].includes(input.mode);
const referencesHeader = isThreadedReply
  ? uniqueMessageIdChain([parentEmailRow.references_header, parentInternetMessageId])
  : '';
const localMessageId = '<case-' + input.case_id + '-' + randomToken() + '@ticket.proxy.shortcentral.com>';
const headers = [
  ['From', encodeAddress(input.sender_name, input.reply_to)],
  ['To', sanitizeAddressHeader(actualRecipient)],
  ['Reply-To', input.reply_to],
  ['Subject', encodeHeaderValue(input.rendered_subject)],
  ['Message-ID', localMessageId],
  ['MIME-Version', '1.0'],
];
if (actualCc) headers.splice(2, 0, ['Cc', sanitizeAddressHeader(actualCc)]);
if (isThreadedReply && parentInternetMessageId) headers.push(['In-Reply-To', parentInternetMessageId]);
if (isThreadedReply && referencesHeader) headers.push(['References', referencesHeader]);
headers.push(['Content-Type', input.email_type === 'html' ? 'text/html; charset=UTF-8' : 'text/plain; charset=UTF-8']);
headers.push(['Content-Transfer-Encoding', 'base64']);
const bodyBase64 = Buffer.from(combinedMessage, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n').trim();
const rawMime = headers.map(([name, value]) => name + ': ' + value).join('\r\n') + '\r\n\r\n' + bodyBase64;
const gmailRaw = Buffer.from(rawMime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
return [{
  json: {
    case_id: input.case_id,
    case_title: caseRow.title || '',
    mode: input.mode,
    reply_quote_mode: input.reply_quote_mode,
    reply_to_case_email_id: input.reply_to_case_email_id,
    template_key: input.template_key,
    signature_template_key: input.signature_template_key,
    return_url: input.return_url,
    n8n_base_url: input.n8n_base_url,
    delivery_mode: input.delivery_mode,
    intended_recipient: intendedRecipient,
    intended_cc: intendedCc,
    actual_recipient: actualRecipient,
    actual_cc: actualCc,
    sender_name: input.sender_name,
    reply_to: input.reply_to,
    rendered_subject: input.rendered_subject,
    rendered_message: input.rendered_message,
    rendered_signature: input.rendered_signature,
    email_type: input.email_type,
    combined_message: combinedMessage,
    gmail_raw: gmailRaw,
    gmail_thread_id: isThreadedReply ? clean(parentEmailRow.gmail_thread_id) : '',
    local_message_id: localMessageId,
    in_reply_to_message_id: isThreadedReply ? parentInternetMessageId : '',
    references_header: referencesHeader,
    parent_case_email_id: ['reply', 'reply_all', 'forward'].includes(input.mode) ? clean(parentEmailRow.id) : '',
    open_tracking_token: trackingToken,
    open_tracking_enabled: Boolean(input.open_tracking_enabled && trackingToken),
    open_tracking_status: input.open_tracking_enabled && trackingToken ? 'Not Opened' : 'Not Tracked',
    tracking_pixel_url: trackingUrl,
    raw_mime_preview: rawMime,
  },
}];

const payload = $('Build Send Payload').first()?.json ?? {};
const sendResponse = $('Send Gmail Message').first()?.json ?? {};
const gmailDetail = $('Fetch Sent Gmail Message').first()?.json ?? {};
const sqlLiteral = (value) => value === null || value === undefined ? 'NULL' : "'" + String(value).replace(/'/g, "''") + "'";
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const headerValue = (name) => {
  const headers = gmailDetail.payload?.headers || gmailDetail.message?.payload?.headers || [];
  const found = Array.isArray(headers) ? headers.find((header) => String(header.name || '').toLowerCase() === String(name).toLowerCase()) : null;
  return clean(found?.value);
};
const messageId = clean(sendResponse.id || gmailDetail.id || gmailDetail.message?.id);
const threadId = clean(sendResponse.threadId || gmailDetail.threadId || gmailDetail.message?.threadId || payload.gmail_thread_id);
const internetMessageId = headerValue('Message-ID') || payload.local_message_id || '';
const inReplyTo = headerValue('In-Reply-To') || payload.in_reply_to_message_id || '';
const referencesHeader = headerValue('References') || payload.references_header || '';
const recipients = JSON.stringify({
  to: payload.intended_recipient,
  cc: payload.intended_cc,
  actual_to: payload.actual_recipient,
  actual_cc: payload.actual_cc,
  delivery_mode: payload.delivery_mode,
  mode: payload.mode,
  reply_quote_mode: payload.reply_quote_mode,
  reply_to: payload.reply_to,
});
const metadata = JSON.stringify({
  send_mode: payload.mode,
  reply_quote_mode: payload.reply_quote_mode,
  gmail_send_response: sendResponse,
  tracking_pixel_url: payload.tracking_pixel_url || null,
});
const bodyHtmlSql = payload.email_type === 'html' ? sqlLiteral(payload.combined_message) : 'NULL';
const bodyTextSql = payload.email_type === 'html' ? 'NULL' : sqlLiteral(payload.combined_message);
const parentSql = payload.parent_case_email_id ? sqlLiteral(payload.parent_case_email_id) + '::uuid' : 'NULL';
const sql = [
  'WITH logged_email AS (',
  '  INSERT INTO public.case_emails (case_id, direction, subject, body_html, body_text, recipients, template_key, signature_template_key, delivery_mode, gmail_message_id, gmail_thread_id, internet_message_id, in_reply_to_message_id, references_header, parent_case_email_id, open_tracking_token, open_tracking_enabled, open_tracking_status, metadata, created_by, sent_at)',
  '  VALUES (' + [
    sqlLiteral(payload.case_id) + '::uuid',
    sqlLiteral('outgoing'),
    sqlLiteral(payload.rendered_subject),
    bodyHtmlSql,
    bodyTextSql,
    sqlLiteral(recipients) + '::jsonb',
    sqlLiteral(payload.template_key),
    sqlLiteral(payload.signature_template_key),
    sqlLiteral(payload.delivery_mode),
    sqlLiteral(messageId),
    sqlLiteral(threadId),
    sqlLiteral(internetMessageId),
    sqlLiteral(inReplyTo),
    sqlLiteral(referencesHeader),
    parentSql,
    payload.open_tracking_token ? sqlLiteral(payload.open_tracking_token) : 'NULL',
    payload.open_tracking_enabled ? 'true' : 'false',
    sqlLiteral(payload.open_tracking_status || 'Not Tracked'),
    sqlLiteral(metadata) + '::jsonb',
    sqlLiteral('case-tracking'),
    'now()'
  ].join(', ') + ')',
  '  RETURNING case_id',
  '), updated_case AS (',
  '  UPDATE public.cases',
  "  SET status = 'Waiting', updated_at = now(), last_outbound_at = now()",
  '  WHERE id = (SELECT case_id FROM logged_email)',
  '  RETURNING id',
  ')',
  'SELECT id::text AS case_id FROM updated_case'
].join('\n');
return [{ json: { ...payload, gmail_message_id: messageId, gmail_thread_id: threadId, internet_message_id: internetMessageId, sql } }];

const item = $('Build Log SQL').first()?.json ?? {};
const updated = $('Log Outbound Email').first()?.json ?? {};
let redirectTo = item.return_url || (item.n8n_base_url + '/webhook/case-tracking?view=dashboard');
if (updated.case_id) redirectTo = item.n8n_base_url + '/webhook/case-tracking?view=case&id=' + encodeURIComponent(updated.case_id);
redirectTo += (redirectTo.includes('?') ? '&' : '?') + 'message=' + encodeURIComponent('Email sent');
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const modeLabel = item.delivery_mode === 'production' ? 'Production' : 'Test';
const recipientSummary = item.delivery_mode === 'production' ? item.actual_recipient : item.actual_recipient + ' (intended recipient: ' + item.intended_recipient + ')';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=' + escapeHtml(redirectTo) + '"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Email sent</title></head><body><p>Email sent in ' + escapeHtml(modeLabel) + ' mode.</p><p>Recipient: ' + escapeHtml(recipientSummary) + '</p><p><a href="' + escapeHtml(redirectTo) + '">Back to case</a></p></body></html>';
return [{ json: { html } }];
